import { ref, computed, onMounted } from 'vue';
import { useCustomerStore } from '@/stores/customerStore';
import type { CustomerSession, Table } from '@/types/customer';

export function useCustomerSession() {
  const store = useCustomerStore();

  const SESSION_KEY = 'nguucat_customer_session';
  const AUTH_KEY = 'nguucat_customer_auth';
  const TABLE_KEY = 'nguucat_customer_table';
  const CART_KEY = 'nguucat_customer_cart';
  const ORDERS_KEY = 'nguucat_customer_orders';

  const session = computed(() => store.session);
  const isAuthenticated = computed(() => store.isAuthenticated);
  const selectedTable = computed(() => store.selectedTable);

  function saveSessionToLocalStorage() {
    if (store.session) {
      localStorage.setItem(SESSION_KEY, JSON.stringify(store.session));
    } else {
      localStorage.removeItem(SESSION_KEY);
    }

    localStorage.setItem(AUTH_KEY, String(store.isAuthenticated));

    if (store.selectedTable) {
      localStorage.setItem(TABLE_KEY, JSON.stringify(store.selectedTable));
    } else {
      localStorage.removeItem(TABLE_KEY);
    }

    localStorage.setItem(CART_KEY, JSON.stringify(store.cart));
  }

  function restoreSessionFromLocalStorage() {
    try {
      const savedSession = localStorage.getItem(SESSION_KEY);
      const savedAuth = localStorage.getItem(AUTH_KEY);
      const savedTable = localStorage.getItem(TABLE_KEY);
      const savedCart = localStorage.getItem(CART_KEY);
      const savedOrders = localStorage.getItem(ORDERS_KEY);

      if (savedAuth === 'true') {
        store.isAuthenticated = true;
      }

      if (savedTable) {
        store.selectedTable = JSON.parse(savedTable);
      }

      if (savedSession) {
        const parsedSession = JSON.parse(savedSession);
        // Revive date objects
        parsedSession.startedAt = new Date(parsedSession.startedAt);
        store.session = parsedSession;
        store.currentView = 'menu';
      }

      if (savedCart) {
        store.cart = JSON.parse(savedCart);
      }

      // Restore orders so they survive page reloads in mock mode
      if (savedOrders && store.orders.length === 0) {
        const parsed = JSON.parse(savedOrders) as any[];
        store.orders = parsed.map(o => ({
          ...o,
          createdAt: typeof o.createdAt === 'string' ? new Date(o.createdAt) : o.createdAt,
        }));
      }
    } catch (e) {
      console.error('Failed to restore customer session from localStorage:', e);
      clearSession();
    }
  }

  function startSession(table: Table, areaName: string, packageId: string = '', adultCount: number = 0, childCount: number = 0) {
    store.selectedTable = table;
    store.isAuthenticated = true;

    const newSession: CustomerSession = {
      id: `sess-${Date.now()}`,
      branchId: store.selectedBranchId || '',
      tableId: table.id,
      tableNumber: table.number,
      areaId: table.areaId,
      areaName: areaName,
      staffId: 'staff-uuid-001',
      guestCount: adultCount + childCount,
      serviceMode: 'buffet',
      languageCode: 'vi',
      startedAt: new Date(),
      status: 'open'
    };

    store.session = newSession;
    store.currentView = 'menu';
    saveSessionToLocalStorage();
  }

  function clearSession() {
    store.resetState();
    localStorage.removeItem(SESSION_KEY);
    localStorage.removeItem(AUTH_KEY);
    localStorage.removeItem(TABLE_KEY);
    localStorage.removeItem(CART_KEY);
    localStorage.removeItem(ORDERS_KEY);
  }

  // Monitor and save changes whenever cart changes
  function syncCart() {
    localStorage.setItem(CART_KEY, JSON.stringify(store.cart));
  }

  return {
    session,
    isAuthenticated,
    selectedTable,
    startSession,
    clearSession,
    restoreSessionFromLocalStorage,
    saveSessionToLocalStorage,
    syncCart
  };
}

import { ref, onUnmounted } from 'vue'
import { supabase } from '@/lib/supabase'
import { useI18nStore } from '@/stores/i18n'

export interface TabletContent {
  id: string
  branch_id: string
  content_type?: string
  type?: string
  title_vi: string | null
  title_en: string | null
  title_ja: string | null
  body_vi: string | null
  body_en: string | null
  body_ja: string | null
  image_url: string | null
  display_order: number
  is_active: boolean
  valid_from: string | null
  valid_until: string | null
  created_at: string
}

export interface TabletSession {
  id: string
  branch_id: string
  table_id: string
  status: 'IDLE' | 'ACTIVE' | 'CHECKOUT_REQUESTED' | 'ENDED'
  language: 'vi' | 'en' | 'ja'
  order_id: string | null
  started_at: string | null
  ended_at?: string | null
  last_activity_at: string
}

export function useTablet() {
  const content = ref<TabletContent[]>([])
  const currentSession = ref<TabletSession | null>(null)
  let realtimeChannel: ReturnType<typeof supabase.channel> | null = null

  // Fetch idle-screen content
  async function fetchContent(branchId: string) {
    const { data, error } = await supabase.rpc('customer_get_tablet_content', {
      p_branch_id: branchId,
    })
    if (error) throw error
    content.value = (data ?? []) as TabletContent[]
    return content.value
  }

  // Touch screen → transition IDLE → ACTIVE
  async function activateSession(tableId: string, branchId: string) {
    const { data, error } = await supabase.rpc('customer_activate_tablet_session', {
      p_branch_id: branchId,
      p_table_id: tableId,
    })
    if (error) throw error
    currentSession.value = data as TabletSession
    localStorage.setItem('tablet_session_id', currentSession.value.id)
    localStorage.setItem('tablet_table_id', currentSession.value.table_id)
    localStorage.setItem('tablet_branch_id', currentSession.value.branch_id)
    return data
  }

  // Set language and sync to session
  async function setLanguage(tableId: string, lang: 'vi' | 'en' | 'ja') {
    let sessionId = currentSession.value?.id || localStorage.getItem('tablet_session_id')
    if (!sessionId) {
      const branchId = localStorage.getItem('tablet_branch_id')
      if (!branchId) throw new Error('Tablet session is not active')
      const session = await activateSession(tableId, branchId)
      sessionId = session.id
    }

    const { data, error } = await supabase.rpc('customer_set_tablet_language', {
      p_session_id: sessionId,
      p_language: lang,
    })

    if (error) throw error
    currentSession.value = data as TabletSession

    // Also update Pinia language store
    const languageStore = useI18nStore()
    languageStore.setLocale(lang)
  }

  // Realtime subscription — auto react when order created or status changes
  function subscribeToSession(tableId: string, onUpdate?: (s: TabletSession) => void) {
    unsubscribe()

    realtimeChannel = supabase
      .channel(`tablet_session_${tableId}`)
      .on('postgres_changes', {
        event: 'UPDATE',
        schema: 'public',
        table: 'tablet_sessions',
        filter: `table_id=eq.${tableId}`
      }, payload => {
        const session = payload.new as TabletSession
        currentSession.value = session
        if (onUpdate) onUpdate(session)
      })
      .subscribe()
  }

  function unsubscribe() {
    if (realtimeChannel) {
      supabase.removeChannel(realtimeChannel)
      realtimeChannel = null
    }
  }

  onUnmounted(() => {
    unsubscribe()
  })

  return {
    content,
    currentSession,
    fetchContent,
    activateSession,
    setLanguage,
    subscribeToSession,
    unsubscribe
  }
}

